20	export type QuoteResult = {
21	  premium: number;
22	};
23	
24	export type ScenarioOutcome = {
25	  results: QuoteResult[];
26	};
27	
28	const PROCESSING_FEE = 5;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	const FIRST_INSURANCE_PERCENT = 10;
40	
41	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
42	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
43	// intermediates to stay exact, so every percentage goes through here.
44	const PERCENT_WHOLE = 100;
45	
46	const percentOf = (amount: number, percent: number): number =>
47	  (amount * percent) / PERCENT_WHOLE;
48	
49	// Rounding always favours MHPCO: premiums round up, payouts round down.
50	const roundPremium = (amount: number): number => Math.ceil(amount);
51	
52	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
53	
54	const BLOCK_SIZE = 3;
55	const BLOCK_BASE_PREMIUM = 60;
56	
57	const countByType = (items: Item[]): Map<string, number> => {
58	  const counts = new Map<string, number>();
59	  for (const item of items) {
60	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
61	  }
62	  return counts;
63	};
64	
65	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
66	
67	// A building block is exactly 3 alike components. Blocks are only offered on
68	// components, never on main items, and only at exactly 3 — 4 runes are priced
69	// per item, not as a block plus one.
70	const formsBuildingBlock = (type: string, count: number): boolean =>
71	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
72	
73	// A group of alike items is priced as a building block if it forms one, and
74	// per item otherwise.
75	const groupBasePremiumOf = (type: string, count: number): number =>
76	  formsBuildingBlock(type, count)
77	    ? BLOCK_BASE_PREMIUM
78	    : count * basePremiumOfType(type);
79	
80	// The policy base premium is the sum of the base premiums of each group of
81	// alike items.
82	const policyBasePremiumOf = (items: Item[]): number =>
83	  [...countByType(items)].reduce(
84	    (total, [type, count]) => total + groupBasePremiumOf(type, count),
85	    0,
86	  );
87	
88	const CURSE_PERCENT = 50;
89	
90	// Item-specific surcharges apply to the base premium of the affected item,
91	// not to the policy total.
92	const itemSurchargesOf = (items: Item[]): number =>
93	  items.reduce(
94	    (total, item) =>
95	      total +
96	      (item.cursed ? percentOf(basePremiumOfType(item.type), CURSE_PERCENT) : 0),
97	    0,
98	  );
99	
100	const quoteStep = (step: Step): QuoteResult => {
101	  const basePremium = policyBasePremiumOf(step.items);
102	  const itemSurcharges = itemSurchargesOf(step.items);
103	  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
104	
105	  return {
106	    premium: roundPremium(
107	      basePremium + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
108	    ),
109	  };
110	};
111	
112	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
113	  results: scenario.steps.map(quoteStep),
114	});
